<template>
  <div class="page"><AppNav />
    <main class="collab">
      <aside class="side panel">
        <button class="primary wide" @click="createDialog = true">＋ 创建学习群</button>
        <div class="side-title"><b>学习协作</b><button @click="friendDialog = true">添加好友</button></div>
        <p class="label">我的会话</p>
        <button v-for="item in conversations" :key="item.id" class="conversation" :class="{ active: item.id === currentId }" @click="open(item.id)"><span class="conversation-avatar"><AvatarBadge :value="item.type === 'private' ? item.peer_avatar : ''" :fallback="item.type === 'group' ? '👥' : '🌿'" :alt="item.title" /></span><div><b>{{ item.title }}</b><small>{{ item.last_message || '还没有消息' }}</small></div><em v-if="item.unread_count" class="unread">{{ item.unread_count > 99 ? '99+' : item.unread_count }}</em></button>
        <p class="label">我的学习伙伴</p>
        <div v-for="friend in friends" :key="friend.id" class="friend"><button class="avatar tiny" @click="profile(friend.id)"><AvatarBadge :value="friend.avatar" :alt="friend.name" /></button><span>{{ friend.name }}<small>{{ friend.college }}</small></span><button class="text" @click="privateChat(friend.id)">私聊</button><button class="text" @click="friendAgent(friend.id)">Agent</button></div>
        <p v-if="requests.length" class="label">新的好友申请</p>
        <div v-for="request in requests" :key="request.id" class="request">{{ request.name }}<button @click="accept(request.id)">接受</button></div>
        <p v-if="friendAgentRequests.length" class="label">Agent 访问申请</p>
        <div v-for="request in friendAgentRequests" :key="request.id" class="request">{{ request.name }} 想与您的 Agent 对话 <button @click="decideFriendAgent(request.id, 'approve')">同意</button><button class="text" @click="decideFriendAgent(request.id, 'reject')">拒绝</button></div>
      </aside>
      <section class="chat panel">
        <template v-if="current">
          <header><div><span class="eyebrow">{{ current.type === 'group' ? 'STUDY GROUP' : 'PRIVATE CHAT' }}</span><h1>{{ current.title }}</h1><p>{{ current.member_count }} 位成员 · {{ current.type === 'group' ? '共同制定复习清单、分工与交流' : '与学习伙伴一对一交流' }}</p></div><div class="header-actions" v-if="current.type === 'group'"><button class="soft" @click="openWorkspace">群任务与复盘</button><button class="soft" @click="membersDialog = true">成员与 Agent</button><button v-if="isOwner" class="soft" @click="agentRequestsDialog = true">审批 Agent <em v-if="agentRequests.length">{{ agentRequests.length }}</em></button></div></header>
          <template v-if="current.type === 'group' && myAgentInGroup"><div v-if="agentBarCollapsed" class="agent-restore"><button type="button" aria-label="展开 Agent 偏好" title="展开 Agent 偏好" @click="agentBarCollapsed = false">⌄</button></div><div v-else class="agent-bar"><span class="agent-mark"><AvatarBadge :value="meMember?.agent_avatar || '✦'" :alt="meMember?.agent_name || '我的 Agent'" /></span><b>{{ meMember?.agent_name || '我的 Agent' }}</b><span>已获准进入本群</span><el-switch :model-value="Boolean(meMember?.agent_auto_reply)" @change="toggleMyAgent" active-text="实时参与偏好" inactive-text="仅旁听" /><button class="agent-toggle" type="button" @click="agentBarCollapsed = true">收起</button></div></template>
          <div ref="messageBox" class="messages">
            <article v-for="message in messages" :key="message.id" :class="{ mine: message.sender_id === me.id && message.sender_type === 'user', agent: message.sender_type === 'agent' }">
              <button class="avatar" @click="profile(message.profile_user_id, message.sender_type === 'agent')"><AvatarBadge :value="message.sender_avatar" :alt="message.sender_name" /></button>
              <div>
                <button class="sender" @click="profile(message.profile_user_id, message.sender_type === 'agent')">{{ message.sender_id === me.id && message.sender_type === 'user' ? '我' : message.sender_name }}</button>
                <div v-if="message.sender_type === 'agent'" class="group-markdown" v-html="renderLearningMarkdown(stripAgentDisplayPrefix(message.content, message.sender_name))"></div>
                <p v-else>{{ message.content }}</p>
                <time>{{ formatTime(message.created_at) }}</time>
              </div>
            </article>
            <div v-if="!messages.length" class="empty">开始一段有目标的学习讨论吧。</div>
          </div>
          <form @submit.prevent="send"><div v-if="current.type === 'group' && groupAgents.length" class="mentions"><span>@ 提问：</span><button v-for="agent in groupAgents" :key="agent.id" type="button" @click="input += `@${agent.agent_name} `"><AvatarBadge class="mention-avatar" :value="agent.agent_avatar" :alt="agent.agent_name" /> {{ agent.agent_name }}</button></div><div class="send-row"><input v-model="input" maxlength="2000" :placeholder="current.type === 'group' ? '输入消息；使用 @Agent名称 向指定 Agent 提问' : '输入学习讨论内容'" /><button class="primary">发送</button></div></form>
        </template><div v-else class="no-chat"><div>◌</div><h2>选择一个学习会话</h2><p>添加伙伴后，可以发起私聊或创建复习群。</p></div>
      </section>
    </main>
    <el-dialog v-model="createDialog" title="创建学习群" width="440px"><el-form label-position="top"><el-form-item label="群名称"><el-input v-model="group.title" placeholder="如：数据结构期末复习小组" /></el-form-item><el-form-item label="邀请学习伙伴"><el-select v-model="group.member_ids" multiple style="width:100%"><el-option v-for="f in friends" :key="f.id" :label="f.name + ' · ' + f.college" :value="f.id" /></el-select></el-form-item></el-form><template #footer><button class="primary" @click="createGroup">创建群聊</button></template></el-dialog>
    <el-dialog v-model="friendDialog" title="添加学习伙伴" width="440px"><el-input v-model="search" placeholder="输入姓名或学号搜索" @input="findUsers" /><div v-for="user in found" :key="user.id" class="found"><button class="avatar" @click="profile(user.id)"><AvatarBadge :value="user.avatar" :alt="user.name" /></button><div><b>{{ user.name }}</b><small>{{ user.student_id }} · {{ user.college }}</small></div><button @click="requestFriend(user.id)">添加</button></div></el-dialog>
    <el-dialog v-model="membersDialog" title="群成员与 Agent" width="520px"><div v-for="m in members" :key="m.id" class="member"><button class="avatar" @click="profile(m.id)"><AvatarBadge :value="m.avatar" :alt="m.name" /></button><div class="member-name"><button class="sender" @click="profile(m.id)">{{ m.name }}</button><small>{{ m.college }}</small></div><template v-if="m.agent_in_group"><button class="avatar agent-avatar" @click="profile(m.id, true)"><AvatarBadge :value="m.agent_avatar" :alt="m.agent_name" /></button><button class="sender" @click="profile(m.id, true)">{{ m.agent_name }}</button></template></div><div v-if="isOwner" class="invite"><el-select v-model="inviteFriendId" placeholder="选择尚未入群的好友"><el-option v-for="f in availableFriends" :key="f.id" :label="f.name" :value="f.id" /></el-select><button class="primary" @click="inviteMember">邀请好友</button></div><button v-if="!myAgentInGroup" class="primary agent-request" @click="requestMyAgent">邀请我的 Agent 入群（群主审批）</button></el-dialog>
    <el-dialog v-model="workspaceDialog" title="群学习协作空间" width="620px"><div class="workspace-panel"><p>只有你主动开启的摘要才会被小组协作 Agent 使用；不会共享私聊、完整计划、课表或个人 Agent 聊天。</p><div class="workspace-head"><b>已加入的个人 Agent</b><small>{{ (workspace.agents || []).length }} 个 Agent 可参与群学习协作</small></div><div v-if="!(workspace.agents || []).length" class="muted">暂时没有 Agent 加入本群；可在“成员与 Agent”中申请邀请自己的 Agent。</div><div v-for="agent in workspace.agents || []" :key="agent.owner_id" class="group-agent-row"><AvatarBadge :value="agent.agent_avatar" :alt="agent.agent_name" /><span><b>{{ agent.agent_name }}</b><small>{{ agent.owner_name }} 的 Agent · {{ agent.auto_reply ? '实时参与已开启' : '仅 @ 时回答' }}</small></span><button v-if="isOwner || agent.owner_id === me.id" class="text" @click="removeGroupAgent(agent)">移出</button></div><hr><div class="consent-row"><span>共享我的薄弱知识点摘要</span><el-switch v-model="workspaceConsent.share_mastery" /></div><div class="consent-row"><span>共享我的待完成计划数量</span><el-switch v-model="workspaceConsent.share_plan_summary" /></div><button class="soft" @click="saveWorkspaceConsent">保存共享设置</button><hr><div class="workspace-head"><b>群任务</b><button class="soft" @click="facilitateGroup">✨ 生成协作建议</button></div><div v-for="task in workspace.tasks || []" :key="task.id" class="task-row"><div><b>{{ task.title }}</b><small>{{ task.assignee_name || '待认领' }} · {{ task.due_date || '无截止日期' }}<br>{{ task.description }}</small></div><button v-if="task.status !== 'done'" class="soft" @click="updateTask(task, 'doing')">进行中</button><button v-if="task.status !== 'done'" class="primary" @click="updateTask(task, 'done')">完成</button><em v-else>已完成</em></div><div class="task-create"><el-input v-model="newTask.title" placeholder="新建群任务" /><el-select v-model="newTask.assignee_id" clearable placeholder="负责人（可选）"><el-option v-for="m in workspace.members || []" :key="m.id" :label="m.name" :value="m.id" /></el-select><button class="primary" @click="createGroupTask">添加任务</button></div><hr><b>已授权学习摘要</b><div v-if="!(workspace.shared_learning || []).length" class="muted">暂无成员授权共享学习摘要。</div><div v-for="item in workspace.shared_learning || []" :key="item.user_id" class="shared-row"><b>{{ item.name }}</b><small v-if="item.weak_points?.length">薄弱重点：{{ item.weak_points.map(point => point.name).join('、') }}</small><small v-if="item.plan_summary !== undefined">待完成计划：{{ item.plan_summary }} 项</small></div><div v-if="workspace.latest_summary" class="summary-box"><b>最近一次群复习建议</b><p>{{ workspace.latest_summary.content }}</p><ul><li v-for="(item,index) in workspace.latest_summary.agenda" :key="index">{{ item }}</li></ul><button v-if="workspace.latest_summary.task_proposals?.length" class="primary" @click="importProposals(workspace.latest_summary.id)">将建议导入群任务</button></div></div></el-dialog>
    <el-dialog v-model="agentRequestsDialog" title="等待审批的 Agent" width="470px"><div v-if="!agentRequests.length" class="empty">暂无待审批申请。</div><div v-for="r in agentRequests" :key="r.id" class="request-line"><span><AvatarBadge class="request-agent-avatar" :value="r.agent_avatar" :alt="r.agent_name" /> <b>{{ r.agent_name }}</b> · {{ r.name }} 的 Agent</span><span><button class="soft" @click="handleAgentRequest(r.id, 'reject')">拒绝</button><button class="primary" @click="handleAgentRequest(r.id, 'approve')">同意</button></span></div></el-dialog>
  </div>
</template>
<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import AppNav from '../components/AppNav.vue'
import AvatarBadge from '../components/AvatarBadge.vue'
import { api, post } from '../utils/api'
import { renderLearningMarkdown, stripAgentDisplayPrefix } from '../utils/learningMarkdown'
const router = useRouter(); const conversations = ref([]), friends = ref([]), requests = ref([]), friendAgentRequests = ref([]), messages = ref([]), members = ref([]), agentRequests = ref([]); const currentId = ref(null), input = ref(''), createDialog = ref(false), friendDialog = ref(false), membersDialog = ref(false), agentRequestsDialog = ref(false), search = ref(''), found = ref([]), inviteFriendId = ref(null), group = ref({ title: '', member_ids: [] }), messageBox = ref(null), agentBarCollapsed = ref(false); let timer
const workspaceDialog = ref(false), workspace = ref({ tasks: [], members: [], shared_learning: [], latest_summary: null }), workspaceConsent = ref({ share_mastery: false, share_plan_summary: false }), newTask = ref({ title: '', assignee_id: null })
const me = computed(() => JSON.parse(localStorage.getItem('user') || '{}')); const current = computed(() => conversations.value.find(x => x.id === currentId.value)); const isOwner = computed(() => current.value?.owner_id === me.value.id); const meMember = computed(() => members.value.find(m => m.id === me.value.id)); const myAgentInGroup = computed(() => Boolean(meMember.value?.agent_in_group)); const groupAgents = computed(() => members.value.filter(m => m.agent_in_group)); const availableFriends = computed(() => friends.value.filter(f => !members.value.some(m => m.id === f.id)))
const formatTime = value => {
  if (!value) return ''
  const text = String(value).trim()
  const date = new Date(/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(text) ? `${text.replace(' ', 'T')}Z` : text)
  return Number.isNaN(date.getTime()) ? '' : date.toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false })
}
async function load () { [conversations.value, friends.value, requests.value, friendAgentRequests.value] = await Promise.all([api('/conversations'), api('/friends'), api('/friend-requests'), api('/friend-agent/requests')]); if (conversations.value[0] && !currentId.value) await open(conversations.value[0].id) }
async function open (id) { currentId.value = id; agentBarCollapsed.value = false; await refreshCurrent(); const conversation = conversations.value.find(item => item.id === id); if (conversation) conversation.unread_count = 0; await nextTick(); if (messageBox.value) messageBox.value.scrollTop = messageBox.value.scrollHeight }
async function refreshCurrent () { if (!currentId.value) return; messages.value = await api(`/conversations/${currentId.value}/messages`); if (current.value?.type === 'group') { members.value = await api(`/conversations/${currentId.value}/members`); agentRequests.value = isOwner.value ? await api(`/conversations/${currentId.value}/agent-requests`) : [] } else members.value = [] }
async function send () { const content = input.value.trim(); if (!content) return; const targets = current.value?.type === 'group' ? groupAgents.value.filter(agent => content.includes(`@${agent.agent_name}`)) : []; try { await post(`/conversations/${currentId.value}/messages`, { content }); input.value = ''; for (const agent of targets) await post(`/conversations/${currentId.value}/agent-ask`, { agent_owner_id: agent.id, question: content }); await refreshCurrent(); await nextTick(); if (messageBox.value) messageBox.value.scrollTop = messageBox.value.scrollHeight; await load() } catch (e) { ElMessage.error(e.message) } }
async function privateChat (friendId) { try { const data = await post('/conversations/private', { friend_id: friendId }); await load(); await open(data.id) } catch (e) { ElMessage.error(e.message) } }
async function createGroup () { try { const data = await post('/conversations', group.value); createDialog.value = false; group.value = { title: '', member_ids: [] }; await load(); await open(data.id) } catch (e) { ElMessage.error(e.message) } }
async function findUsers () { found.value = search.value.trim() ? await api(`/users/search?q=${encodeURIComponent(search.value)}`) : [] }
async function requestFriend (id) { try { await post('/friend-requests', { user_id: id }); ElMessage.success('好友申请已发送') } catch (e) { ElMessage.error(e.message) } }
async function accept (id) { try { await post(`/friend-requests/${id}/accept`, {}); await load(); ElMessage.success('已成为好友') } catch (e) { ElMessage.error(e.message) } }
async function friendAgent (ownerId) { try { const state = await api(`/friend-agents/${ownerId}/access`); if (state.status === 'approved') return router.push(`/friend-agent/${ownerId}`); if (state.status === 'pending') return ElMessage.info('已申请访问，等待好友同意'); const data = await post(`/friend-agents/${ownerId}/access`, {}); ElMessage.success(data.status === 'approved' ? '已获得授权' : '已提交 Agent 访问申请') } catch (e) { ElMessage.error(e.message) } }
async function decideFriendAgent (id, action) { try { const data = await api(`/friend-agent/requests/${id}`, { method: 'PATCH', body: JSON.stringify({ action }) }); ElMessage.success(data.message); await load() } catch (e) { ElMessage.error(e.message) } }
async function inviteMember () { try { await post(`/conversations/${currentId.value}/members`, { user_id: inviteFriendId.value }); inviteFriendId.value = null; await refreshCurrent(); await load(); ElMessage.success('已邀请好友入群') } catch (e) { ElMessage.error(e.message) } }
async function requestMyAgent () { try { await post(`/conversations/${currentId.value}/agent-requests`, {}); await refreshCurrent(); ElMessage.success('已提交申请，等待群主审批') } catch (e) { ElMessage.error(e.message) } }
async function handleAgentRequest (id, action) { try { await api(`/conversations/${currentId.value}/agent-requests/${id}`, { method: 'PATCH', body: JSON.stringify({ action }) }); await refreshCurrent(); ElMessage.success(action === 'approve' ? '已同意 Agent 入群' : '已拒绝申请') } catch (e) { ElMessage.error(e.message) } }
async function toggleMyAgent (autoReply) { try { const data = await api(`/conversations/${currentId.value}/my-agent`, { method: 'PATCH', body: JSON.stringify({ auto_reply: autoReply }) }); ElMessage.success(data.message); await refreshCurrent() } catch (e) { ElMessage.error(e.message) } }
async function removeGroupAgent (agent) { try { await api(`/conversations/${currentId.value}/group-agents/${agent.owner_id}`, { method: 'DELETE' }); ElMessage.success('已移出该 Agent'); await refreshCurrent(); await refreshWorkspace() } catch (e) { ElMessage.error(e.message) } }
async function refreshWorkspace () { if (!currentId.value) return; workspace.value = await api(`/conversations/${currentId.value}/workspace`); workspaceConsent.value = { ...workspace.value.my_consent } }
async function openWorkspace () { try { await refreshWorkspace(); workspaceDialog.value = true } catch (e) { ElMessage.error(e.message) } }
async function saveWorkspaceConsent () { try { const data = await api(`/conversations/${currentId.value}/learning-consent`, { method: 'PATCH', body: JSON.stringify(workspaceConsent.value) }); ElMessage.success(data.message); await refreshWorkspace() } catch (e) { ElMessage.error(e.message) } }
async function createGroupTask () { const title = newTask.value.title.trim(); if (!title) return ElMessage.warning('请填写群任务标题'); try { const data = await post(`/conversations/${currentId.value}/tasks`, { title, assignee_id: newTask.value.assignee_id }); ElMessage.success(data.message); newTask.value = { title: '', assignee_id: null }; await refreshWorkspace() } catch (e) { ElMessage.error(e.message) } }
async function updateTask (task, status) { try { const data = await api(`/conversations/${currentId.value}/tasks/${task.id}`, { method: 'PATCH', body: JSON.stringify({ status }) }); ElMessage.success(data.message); await refreshWorkspace() } catch (e) { ElMessage.error(e.message) } }
async function facilitateGroup () { try { const data = await post(`/conversations/${currentId.value}/facilitate`, {}); ElMessage.success(data.message); await refreshWorkspace() } catch (e) { ElMessage.error(e.message) } }
async function importProposals (summaryId) { try { const data = await post(`/conversations/${currentId.value}/summaries/${summaryId}/import-tasks`, {}); ElMessage.success(data.message); await refreshWorkspace() } catch (e) { ElMessage.error(e.message) } }
function profile (id, agent = false) { router.push({ path: `/profile/${id}`, query: agent ? { agent: '1' } : {} }) }
onMounted(async () => { try { await load(); timer = setInterval(async () => { try { await refreshCurrent(); await load() } catch {} }, 4000) } catch (e) { ElMessage.error(e.message) } }); onBeforeUnmount(() => clearInterval(timer))
</script>
<style scoped>
